SELECT t.*, u.real_name AS user_real_name FROM ai_agent_traces t LEFT JOIN users u ON u.id = t.user_id
AND t.status = #{status}
AND (t.user_query LIKE CONCAT('%', #{keyword}, '%') OR t.tool_sequence LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY t.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ai_agent_traces t LEFT JOIN users u ON u.id = t.user_id
AND t.status = #{status}
AND (t.user_query LIKE CONCAT('%', #{keyword}, '%') OR t.tool_sequence LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%'))
